import java.io.StringReader;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

class ExampleTest {
    @Test
    void checksResources() throws Exception {
        try (StringReader reader = new StringReader("a")) {
            assertEquals('a', reader.read());
        }

        try {
            assertEquals(4, 2 + 2);
        } finally {
            System.out.println("cleanup");
        }
    }
}

import org.junit.jupiter.api.Test;

class ExampleTest {
    @Test
    void checksLoops() {
        for (int i = 0; i < 2; i++) {
            System.out.println(i);
        }

        for (int value : new int[] {1, 2}) {
            System.out.println(value);
        }

        int counter = 0;
        while (counter < 2) {
            counter++;
        }

        do {
            counter--;
        } while (counter > 0);
    }
}

import org.junit.jupiter.api.Test;

class ExampleTest {
    @Test
    void checksLoops() {
        for (int i = 0; i < 2; i++) {
            System.out.println(i);
        }

        for (int value : new int[] {1, 2}) {
            System.out.println(value);
        }

        int counter = 0;
        while (counter < 2) {
            counter++;
        }

        do {
            counter--;
        } while (counter > 0);
    }
}

